    except: continue
    if 'order_items' in e.get('msg',''):
        m=e['ts'][:16]; kind='batch' if ' IN (?)' in e['msg'] else 'per-row'
        c[(m,kind)]+=1
        if e.get('duration_ms') is not None: d[(m,kind)].append(e['duration_ms'])
for k in sorted(c): 
    v=d.get(k,[]); print(k,c[k], (sum(v)/len(v)) if v else '-')
EOF
